pub fn truncate_safe(s: &str, max_bytes: usize) -> &str {
    &s[..max_bytes]
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn test_truncate_multibyte() {
        let s = "Hello, 世界!";
        let res = truncate_safe(s, 8);
        assert!(res.len() <= 8);
    }
}
